import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Login from "./components/Login";
import AdminDashboard from "./components/AdminDashboard";
import UserDashboard from "./components/UserDashboard";
import SuperAdminDashboard from "./components/SuperAdminDashboard";
import AddExamCenter from "./pages/AddExamCenter";
import AddUser from "./pages/AddUser";
import ViewExamCenter from "./pages/ViewExamCenter";

function App() {
    return (
        <Router>
            <Routes>
                <Route path="/" element={<Login />} />
                <Route path="/admin" element={<AdminDashboard />} />
                <Route path="/user" element={<UserDashboard />} />
                <Route path="/superadmin" element={<SuperAdminDashboard />} />
                <Route path="/superadmin/add-exam-center" element={<AddExamCenter />} />
                <Route path="/admin/add-user" element={<AddUser />} />
                <Route path="/superadmin/view-exam-center/:id" element={<ViewExamCenter />} />
            </Routes>
        </Router>
    );
}

export default App;
